'rseg';		#endif	#endif	/* Include the separately compiled resources */	include "CalcUtilities.rsrc" not 'ckid';#else	#if qDebug | qPerform		include kDebugRsrcName not 'ckid';	#endif	include kDialogRsrcName not 'ckid';	include kGeneralRsrcName not 'ckid';	include kPrintingRsrcName not 'ckid';#endif // !THINK_Rez//--------------------------------------------------------------------------------------------------// CONSTANTS //--------------------------------------------------------------------------------------------------// Finder Information// ------------------#if !defined(THINK_Rez) && !defined(MW_Rez)#define kApplicationName	$$Shell("XAppName")#else#define kApplicationName	TARGET_APPLICATION_NAME#endif // !THINK_Rez#define kSignature			'SS11'			// Application signature // Bundle Constants// ------------------#define kBundleID						128#define kApplicationID					128// Command Numbers For Menu Items// ------------------------------#define cFirstWindow				2001#define cLastWindow					2001#define cFirstDialog				1001#define cLastDialog					1001#define cToggleHilite				3001//--------------------------------------------------------------------------------------------------// RESOURCES FOR MENUS //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// Menu Bars //--------------------------------------------------------------------------------------------------resource 'MBAR' (kMBarDisplayed,#if qNames"DemoSprite MBAR",#endif	purgeable){	{ mApple; mFile; mEdit }};//--------------------------------------------------------------------------------------------------// Menus //--------------------------------------------------------------------------------------------------include kDefaultRsrcName 'CMNU' (mApple);	// Grab the default Apple menusinclude kDefaultRsrcName 'CMNU' (mEdit);		// Grab the default Edit menuresource 'CMNU' (mFile,#if qNames"mFile",#endifpurgeable) {	mFile,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"File",	{	"New Sprite Test Window",	noIcon, "1",	noMark, plain, cFirstWindow;	"-",				noIcon, noKey,	noMark, plain, nocommand;	"Close",			noIcon, "W",	noMark, plain, cClose;	"-",				noIcon, noKey,	noMark, plain, nocommand;	"Quit",				noIcon, "Q",	noMark, plain, cQuit	}};resource 'CMNU' (mBuzzwords,#if qNames"Buzzwords",#endifpurgeable) {	mBuzzwords,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Buzzwords",	 {	/* array: 13 elements */		"Page Setup Change",	noIcon,	noKey,	noMark, plain, cChangePrinterStyle;		"Typing",				noIcon,	noKey,	noMark,	plain, cTyping;	}};//--------------------------------------------------------------------------------------------------// Balloon Help Resources for Menus //--------------------------------------------------------------------------------------------------// Includes resource 'STR#' (kStandardHelpStrings, "Balloon Help String 1")// with our application name substituted in strings#include "HelpStrings.r"#if !qCarboninclude kDefaultRsrcName  'hmnu' (mFile);	include kDefaultRsrcName  'hmnu' (mEdit);	#endif // !qCarbon//--------------------------------------------------------------------------------------------------// RESOURCES FOR VIEWS, DIALOGS, ALERTS etc. //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// About Box//--------------------------------------------------------------------------------------------------resource 'DITL' (phAboutApp,#if qNames"phAboutApp",#endif	purgeable) {	 {	/* array DITLarray: 3 elements */		/* [1] */		{167, 288, 187, 348},		Button {			enabled,			"OK"		};		/* [2] */		{10, 75, 154, 348},		StaticText {			disabled,			"This sample program demonstrates the use of QuickTime sprites as controls."			"\n"			WRITTEN_WITH_MACAPP		};		/* [3] */		{10, 20, 42, 52},		Icon {			disabled,			noteIcon		}	}};include kDefaultRsrcName  'ALRT' (phAboutApp);		// Grab the default about boxinclude kDefaultRsrcName	'aete' (0);					// Grab the default AppleEvent terminologyinclude kDefaultRsrcName  'STR#' (kDefaultCredits);	// Grab the default credits//--------------------------------------------------------------------------------------------------// MultiFinder™ information//--------------------------------------------------------------------------------------------------/* Additional size deltas to be added to partition size */#if qNames#define kNamesSizeDelta 75#else#define kNamesSizeDelta 0#endif#if qDebug#define kDebugSizeDelta 0#else#define kDebugSizeDelta 0#endif#define kModelFarSizeDelta 0#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,					reserved,	reserved,	reserved,	reserved,		/* Suggested partition size */	(2000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(1800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// Icons//--------------------------------------------------------------------------------------------------include kDefaultRsrcName  'ICN#' (kApplicationID);	// MacApp Family large black & white	include kDefaultRsrcName  'ics#' (kApplicationID);	// MacApp Family small black & white	include kDefaultRsrcName  'ics4' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics8' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'icl4' (kApplicationID);	// MacApp Family large 4 bitinclude kDefaultRsrcName  'icl8' (kApplicationID);	// MacApp Family large 8 bit//--------------------------------------------------------------------------------------------------// Memory usage information for DemoSprite//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable){	"DemoSprite, "APPLE_LONG_COPYRIGHT};resource 'FREF' (kApplicationID,#if qNames"DemoSprite Application",#endif	purgeable){	'APPL', 0, ""};resource 'BNDL' (kBundleID,#if qNames"DemoSprite",#endif	purgeable) { kSignature, 0,	{		'ICN#', { 0, kApplicationID },		'FREF', { 0, kApplicationID }	}};resource 'open' (kBundleID){	kSignature, {}};resource 'kind' (kBundleID){	kSignature,	verUS,	{		ftApplicationName, 	"Skeleton",	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x01,	development,	0x01,	verUs,	"1.0d1",	"DemoSprite 1.0d1, Copyright © 1998-2001 by Apple Computer, Inc."};include kDefaultRsrcName  'vers' (2);		// Overall package//--------------------------------------------------------------------------------------------------// Views and other resources.//--------------------------------------------------------------------------------------------------#ifndef MW_Rez		// This Adlib file is included in IconEdit.prj for MW Builds	include "DemoSprite.view" not 'vers';	include "KnobControl.rsrc" not 'ckid';	include "SpriteControl.rsrc" not 'ckid';#endif